/**
 * Normalized OpenAPI source -> ordered explicit overlay refs from docs.json.
 * An empty array means "no overlays, including auto-discovered ones".
 */
export type ExplicitOverlayConfig = Map<string, string[]>;
/** Canonical source key: URLs unchanged, relative paths normalized without leading slash. */
export declare function normalizeOpenApiSourceKey(source: string): string;
/**
 * Walks every `openapi` entry in a (possibly unvalidated) docs or mint config and
 * returns the explicit overlay lists per normalized source. Throws when the same
 * source is configured with two different lists.
 */
export declare function collectOpenApiOverlayConfig(docsConfig: unknown): ExplicitOverlayConfig;
